#include <stdio.h>

int main() {
    for (int i = 0; i < 5; i++) {
        if (i == 3) break;
        printf("%d ", i);
    }
    printf("\n");

    int n = 0;
    while (1) {                  // intentional infinite loop
        if (n >= 3) break;
        printf("n=%d ", n);
        n++;
    }
    printf("\n");
    return 0;
}
